-- Original 30-card CR01 set; all card and artwork IDs are generated by PostgreSQL.
INSERT INTO expansions (code, name, is_active)
VALUES ('CR01', 'Set Dimostrativo', true)
ON CONFLICT (code) DO NOTHING;

INSERT INTO factions (code, name)
VALUES ('NEUTRAL', 'Neutral')
ON CONFLICT (code) DO NOTHING;

CREATE TEMPORARY TABLE initial_set_cards (
    name varchar PRIMARY KEY,
    type_code varchar NOT NULL,
    faction_code varchar NOT NULL,
    rarity_code varchar NOT NULL,
    energy_cost integer,
    power integer,
    value_atk integer,
    value_def integer,
    description varchar,
    flavor_text varchar,
    source_image varchar,
    image_url varchar NOT NULL
) ON COMMIT DROP;

