-- RETURNING captures the generated IDs for artwork references in this same statement.
WITH inserted_cards AS (
    INSERT INTO cards (name, id_expansion, id_type, id_faction, id_rarity,
                       energy_cost, power, value_atk, value_def, description, flavor_text)
    SELECT s.name,
           (SELECT id FROM expansions WHERE code = 'CR01'),
           (SELECT id FROM card_types WHERE code = s.type_code),
           (SELECT id FROM factions WHERE code = s.faction_code),
           (SELECT id FROM rarities WHERE code = s.rarity_code),
           s.energy_cost, s.power, s.value_atk, s.value_def, s.description, s.flavor_text
    FROM initial_set_cards s
    ORDER BY s.name
    RETURNING id, name
)
INSERT INTO cards_arts (id_card, art_code, source_image, url_card_art)
SELECT c.id, 'STANDARD', s.source_image, s.image_url
FROM inserted_cards c JOIN initial_set_cards s ON s.name = c.name
ORDER BY c.id;
